            "b": "簡報 1-22、簡報 1-24。\n體系法源：資安法行政體系架構\n層級 | 角色 | 職責\n決策 | 行政院 | 決定我國整體資安策略\n規劃 | 數位發展部 | 本法主管機關，規劃推動國家資安政策等相關事宜；其下數位發展部資通安全署為指定之資安專責機關，辦理國家資安業務，兼負部分規劃、執行與監管\n監管 | 公務機關的上級或監督機關；特定非公務機關的中央目的事業主管機關 | 監管所屬、所監督、所轄、所管機關之資安管理\n納管 | 公務機關、特定非公務機關 | 落實資安法遵義務\n「所轄公務機關」的定義：在直轄市政府係指直轄市山地原住民區公所及區民代表會；在縣（市）政府係指鄉（鎮、市）公所、鄉（鎮、市）民代表會。\n記法：這四層也可畫成金字塔，由上而下＝決策（行政院）→規劃（數發部）→監管（上級／中央目的事業主管機關）→納管（各機關）。"
