            "b": "簡報 1-26。\n§11 本條新增：\n        公務機關禁止使用危害國家資安產品；\n        例外專案使用須經資安長核可並報主管機關核定；\n        相關辦法由主管機關報請行政院核定。\n§12 應置資通安全長（副首長或適當人員兼任），負責推動及監督機關內資安事務。\n§13 須符合責任等級要求；\n        應訂定、修正及實施資通安全維護計畫。\n§14 每年向上級或監督機關提出資安計畫實施情形；\n       無上級者，分層向主管機關或地方政府提出。\n§15 應稽核所屬或監督機關之資安計畫實施情形；\n       新增地方政府對轄下區、鄉鎮市公所之稽核責任。\n§16 缺失改善報告須向稽核機關提出，並連同稽核結果送交主管機關；\n       稽核機關或主管機關得要求說明或調整。\n§17 應訂定資安事件通報及應變機制；\n       知悉事件應向受實施情形機關及主管機關通報；\n       應提出調查、處理及改善報告；\n       重大事件時受通報機關得提供協助並公告。\n§18 應符合等級要求並設置資通安全專職人員；\n        績效優良者應予獎勵；\n        新增遇重大事件時主管機關得調度資安人員支援。\n§19 本條新增：\n        適任性進行查核；\n        查核未通過者不得辦理涉國家機密之資安業務；\n        查核紀錄應保密處理。"
