            "b": "簡報 1-67。\n可依風險管理範圍與目標，採用不同作法，例如高階風險評鑑作法或詳細風險評鑑作法；在每一循環中作法可能不同，故在不同階段選擇或發展適切的作法。\n兩種作法對照（含優缺點）：\n項目 | 高階風險評鑑 | 詳細風險評鑑\n主要適用對象 | 資通系統 | 資訊資產（一般作法）；以及經分級結果屬高安全等級之資通系統\n判斷依據 | 依「資通安全責任等級分級辦法」之資通系統防護需求分級原則，決定資通系統安全等級 | 對資產進行深度識別與鑑別，並詳細列出可能面臨的威脅與可能存在的弱點\n分析方法 | 直接依資通系統分級方式進行，省時省力 | 可為定量方法、定性方法或二者結合；依資產價值或需被保護的特性，評鑑威脅發生之可能性\n使用時機 | 實作風險管理的第 1 年、第 2 年 | 時間與資源允許時，或於資安事件發生後\n執行步驟 | 分級處理程序：承辦人設定→單位主管檢視（＋資訊主管確認）→資安長核定 | 八個步驟，分屬風險識別、風險分析、風險評估三階段\n控制措施來源 | 參考「安全控制措施參考指引」，依普、中、高選擇適用之安全控制措施 | 依深度識別與鑑別的結果，尋求更適當的風險處理方案\n優點 | ① 一開始採用較簡單作法，容易獲得風險評鑑參與人員接受 ② 把握時效，讓最關鍵且需受保護的資通系統優先被提出與實作 ③ 省時省力，可將資源與預算運用於最有利之處 | ① 對資產深度識別與鑑別，詳列可能面臨的威脅與可能存在的弱點，評鑑結果較精確 ② 藉系統化方式找出應優先處理的資產與對應風險，施予適當防護控制措施以維持持續運作 ③ 依資產價值或需被保護的特性評鑑威脅發生之可能性，風險處理方案更貼合實況\n缺點 | ① 評鑑結果較不精確，可能未識別某些營運過程或系統 ② 無法一次到位：仍須視需要針對高安全等級之資產另行執行詳細風險評鑑 | ① 需考慮時間、耗費程度及專家意見，費時且成本高、依賴專業判斷 ② 須清查盤點所有資訊及資通系統資產，並整合跨部門業務成員組成評鑑組織，執行負擔大\n註：簡報明列優缺點的只有高階作法（見本節「高階風險評鑑的時機、優點與缺點」）；詳細作法的優缺點是由其作法敘述（簡報 1-67、1-76）整理而得。\n一句話記法：資通系統先用高階（依分級），高等級者再做詳細；資訊資產一般直接用詳細。\n口訣：高階＝快、省、粗；詳細＝準、細、貴。\n詳細作法的八個步驟見本節「詳細風險評鑑的作法與八個步驟」。"
