            "b": "簡報 1-71～簡報 1-74。\n用途：業務承辦人依機密性、完整性、可用性及法律遵循性 4 大影響構面，分別評估資通系統發生資安事件時的衝擊，各構面各自定出普、中、高。\n構面 | 事件造成的情事 | 普 | 中 | 高\n機密性 | 資料外洩、未經授權之資訊揭露 | 有限負面影響；一般性資料，不影響機關權益或僅輕微受損 | 嚴重負面影響；敏感性資料，機關權益嚴重受損；涉區域性、地區性個資 | 非常嚴重或災難性；機密性資料，危及國家安全；涉國安機敏、特殊屬性個資、醫療基因犯罪前科、全國性個資\n完整性 | 資料遭竄改、未經授權之修改或破壞 | 有限負面影響；不影響機關權益或僅輕微受損 | 嚴重負面影響；機關權益嚴重受損 | 非常嚴重或災難性；危及國家安全，機關權益非常嚴重受損\n可用性 | 系統故障、無法使用或異常運作 | 有限負面影響；容許中斷時間較長（例 72 小時），業務效能輕微降低 | 嚴重負面影響；容許中斷時間短（無數字），業務效能嚴重降低 | 非常嚴重或災難性；容許中斷時間非常短（例 30 分鐘），效能非常嚴重降低甚至業務停頓\n法律遵循性 | 未遵循相關法令或規範 | 未遵循「其他資通相關法令或規範」；即系統設置或運作於法令有相關規範之情形 | 使機關或其所屬人員受「行政罰、懲戒或懲處」 | 使機關或其所屬人員負「刑事責任」\n看表要點：前三個構面的等級用語完全一樣（有限＝普、嚴重＝中、非常嚴重或災難性＝高），差別只在「事件造成什麼情事」；只有法律遵循性改用責任種類分界。\n共同句型（前三構面）：未經授權之◯◯／中斷，在機關營運、資產或信譽等方面，造成可預期「有限／嚴重／非常嚴重或災難性」負面影響。\n三個必背錨點：\n① 可用性：普＝例 72 小時、高＝例 30 分鐘，中沒有數字只說「時間短」\n② 機密性：區域性或地區性個資＝中、全國性個資＝高\n③ 法律遵循性：行政責任＝中、刑事責任＝高\n各構面逐級的完整法規原文（含機密性「高」級的四種情形）見本節「影響構面一」至「影響構面四」四條重點。"
