            "b": "簡報 2-36。\n要使所有存取行為都可歸責到使用者真實身分，至少應滿足下列六個條件：\n序 | 條件 | 對應構面\n① | 首先必須要具備「唯一識別符」可代表使用者真實身分 | 識別與鑑別\n② | 足夠「強固的使用者鑑別技術」，能防止身分鑑別機制被破解 | 識別與鑑別\n③ | 系統「所有存取路徑」被強制控管 | 存取控制\n④ | 所有存取行為「不論成功或失敗」都被詳實記錄 | 事件日誌與可歸責性\n⑤ | 系統存取紀錄的「時戳代表存取順序」 | 事件日誌與可歸責性\n⑥ | 系統存取紀錄應被妥善保護，「任何人均無法修改或刪除」 | 事件日誌與可歸責性\n這六條橫跨識別鑑別、存取控制、事件日誌三個構面，是複選題的好題材。\n陷阱：④ 是「不論成功或失敗」都要記錄，只記錄失敗或只記錄成功都不夠。"
