            "h": "⭐ 數位信封：結合兩者的優點",
            "b": "簡報 2-72。\n概念：如同將資料裝入信封，只有接收者才能拆開信封；數位信封結合對稱式與非對稱式加解密演算法的優點。\n步驟 | 作法 | 用的是哪一種技術 | 取得的優點\n① | 用對稱式金鑰加密大量資料 | 對稱式加密 | 速度快，適合處理大量資料\n② | 用接收者的公開金鑰加密那把對稱金鑰 | 非對稱式加解密 | 金鑰交換安全，不必事先共享秘密金鑰\n一句話：內容用對稱式加密（快），鑰匙用非對稱式加密（安全）。"
