            "b": "簡報 2-76、簡報 2-77。\n構面目的：確保資通系統及其儲存及處理的資訊不被非法篡改或破壞。\n分級 | 要求 | 作法\n高中普 | 系統之漏洞修復應「測試有效性及潛在影響」，並定期更新 | 先於測試用主機上完成更新可行性評估並通過測試後，始於正式環境進行更新\n高中 | 定期確認資通系統相關漏洞修復之狀態 | 宜注意相關安全漏洞訊息（如 CVE 相關訊息網站、廠商安全通告等）；由弱點掃描與滲透測試等檢出之系統漏洞應設法修復，並定期追蹤修復進度或配合定期檢測作業確認複測\n陷阱：漏洞不能直接在正式環境更新，要先測有效性與潛在影響。"
