            "b": "簡報 2-81、簡報 2-82。\n媒體包含：磁碟、磁帶、光碟及紙張。\n媒體控管的目的：避免儲存在其中的機敏資料外洩。\n媒體控管的八項工作：標示、使用紀錄、完整性檢查、實體存取保護、存放環境保護、運送保護、重用安全、銷毀與丟棄。\n媒體上應清楚標示的六個欄位：名稱與版本、機密等級、建立者、建立日期、保存期限、應銷毀日期。\n陷阱：紙張也是媒體；標示欄位常漏掉「應銷毀日期」。"
