            "b": "簡報 2-95、簡報 2-96、簡報 2-97。\n定義：是一台專屬的硬體或架設在一般硬體上的軟體，依照特定的規則允許或限制傳輸的資料通過網路。\n項目 | 內容\n用途（3 項） | ①區隔不同安全等級網段（如外部網路、內部網路及 DMZ）②過濾資料封包，避免未經授權存取內部網路資源 ③提供稽核與控制存取網路資源\n部署方式（2 項） | ①考量資安需求，妥善劃分 IP 網段與虛擬區域網路 ②建置 2 台防火牆並設定成高可靠度 (High Availability) 運作模式——當主要防火牆出現問題時，次要防火牆即接手主要防火牆的工作\n管理重點（4 項） | ①存取規則的變更應建立管理程序（變更申請、核准及記錄）②存取紀錄應即時匯出存檔，並保留足夠的時間 ③定期產出異常存取統計分析報表，進行異常處理 ④存取控管規則應定期盤查（頻率見下表）\n選購考量（4 項） | ①防火牆本身的安全性 ②可區隔的網路區段數應符合機關需求 ③可支援的傳輸頻寬大小符合機關需求 ④具備「第七層（應用層）」防護能力\n兩個頻率最容易互相干擾，放在一起記：\n項目 | A 級 | B 級 | C 級\n防火牆存取控管規則盤查 | 每年 1 次 | 每 2 年 1 次 | －\n內部資通安全稽核（見單元 4） | 每年 2 次 | 每年 1 次 | 每 2 年 1 次\n數字速記：防火牆盤查是「1／2 年」，內部稽核是「2／1／2 年」——防火牆沒有 C 級。"
