            "h": "⭐⭐ 應用程式防火牆 (WAF)：三種偵測過濾技術",
            "b": "簡報 2-98、簡報 2-99、簡報 2-100、簡報 2-101。\n定義：針對「應用層」封包進行管制的防火牆機制，特別是針對網站應用的防護，常見為網站應用程式防火牆 (WAF)。\n適用：具有對外服務之核心資通系統者，應備應用程式防火牆。\n用途：偵測與防禦針對網站應用程式之攻擊行為，例如 SQL Injection 與 Cross-Site Scripting (XSS) 等。\n三種偵測與過濾技術：\n技術 | 作法 | 特點\n白名單 | 只有列在白名單的網頁與參數才能通過，其他一律拒絕 | 理論上最安全且可防範未知攻擊，但實務上無法學習到 100% 的白名單\n黑名單 | 列在黑名單的網頁與參數一律拒絕 | －\n攻擊特徵判斷 | 比對已知的攻擊特徵 | 目前較常用的作法，但會有誤判與漏判的問題\n類型與部署方式：硬體式、軟體式。\n管理重點：存取規則變更應建立管理程序；異常的網站應用程式攻擊事件應立即匯出並保留足夠時間；應定期分析並處理異常。\n選購考量：處理效能符合網站流量需求；中文 URL 及傳輸內容的判斷能力；HTTPS 加密連線可先在 WAF 解密過濾後再轉到後端網站（IDS／IPS 無法判斷 HTTPS 連線）。\n考點：白名單理論最安全但做不到 100%；WAF 能解 HTTPS、IDS/IPS 不能。"
