            "b": "簡報 3-20。\n定義（逐字背）：是一種資安評估方法，係透過「模擬有心人士之攻擊方式」，對系統或物聯網設備進行安全強度的測試。\n序 | 目的 | 內容\n① | 評估防護能力 | 檢測受測目標在遭遇攻擊活動時之資安防護能力與執行成效\n② | 發現潛在弱點 | 主動找出可能被利用的安全漏洞\n③ | 提供改善建議 | 依據結果提供修補弱點的方法與建議\n④ | 確認弱點已排除 | 透過複測，確認初測找出之資安漏洞已經完成修正\n⑤ | 精進整體防護 | 透過報告及改善建議，檢討與精進受測目標之整體資安防護作為\n與弱點掃描的分界：弱點掃描是「檢查已知弱點」，滲透測試是「模擬攻擊、驗證能不能被打進來」。\n陷阱：④「確認弱點已排除」靠的是複測，最容易被漏掉。"
