            "b": "簡報 3-22、簡報 3-23。\n滲透測試與弱點掃描的執行階段幾乎相同，差別就在多了一道「風險管理」——這是本條標題的重點：\n執行階段 | 弱點掃描 | 滲透測試\n事前準備與了解 | 與目標組織溝通，了解其網路架構與系統環境 | 對受測目標進行資料蒐集與資訊分析，作為執行測試的決策依據\n工具準備 | 合法授權的商業掃描軟體\\n事前更新弱點資料庫 | 合法授權的商業滲透測試軟體\\n事前更新弱點資料庫\n風險管理 | － | 執行具「侵入性質」的檢測作業前，需與組織進行確認，並具備適當應變措施與風險評估後才進行\\n事前需提出對受測目標進行「備份建議」\n執行 | 安排適當掃描時間，通常在非公務時段或與組織協調 | 可針對網際網路及／或內部網路進行\\n網際網路測試通常由遠端進行，內部網路測試則於現場進行\\n安排適當執行時間，通常於非公務時段或與組織協調\\n初測包括「探索、弱點發掘、漏洞利用」\n協助修補與追蹤 | 協助理解弱點、提供修補建議並追蹤修補進度 | 協助組織理解弱點、提供修補建議並追蹤管理\n複掃／複測 | 就初掃報告找出之弱點再次執行複掃，確認是否已成功排除 | 確認先前弱點是否已成功排除\\n若仍有未修補者，服務提供者應協助解決\n必考：滲透測試前要先備份、要先做風險評估與應變措施——這三件事弱點掃描都沒有。"
