            "h": "⭐⭐ 應用安全 vs 架構安全（最強干擾選項）",
            "b": "簡報 3-25、簡報 3-26。\n軟體安全工程探討軟體安全問題的解決方法，兩者分屬不同領域：\n項目 | 應用安全 | 架構安全\n屬於什麼問題 | 軟體工程 | 系統管理\n由什麼來解決 | 設計 | 設定\n陷阱：把「應用安全＝系統管理／由設定解決」與「架構安全＝軟體工程／由設計解決」對調，是最常見的錯誤選項。\n安全要求高的軟體需要特別訂定安全性規格：從實際應用的角度來評估風險；依實際的需求來設計軟體系統降低風險與損害。\n傳統開發與 SSDLC 的對照：\n面向 | 傳統系統開發 | SSDLC 之思維\n導向 | 功能性導向，在最短的時間完成系統的開發與上線 | 在考量系統功能性的同時導入安全性思維\n安全考量 | 缺乏安全性考量的設計，面對日新月異的攻擊手法難以建立有效防護（如 SQL Injection 便是因此而崛起） | 於開發過程中進行各項必要的安全控制措施\n時程與成本 | 開發時程短，但後續維運成本與遭入侵損失高 | 開發時程長，卻降低了系統後續維運的成本與遭受入侵的損失"
