            "b": "簡報 3-40、簡報 3-41、簡報 3-42、簡報 3-43、簡報 3-44。\n健診目的三項：\n整合各資通安全項目的檢視服務作業，提供機關資通安全改善建議\n藉由實施技術面與管理面的相關控制措施，提升機關整體資通安全防護能力\n針對已知弱點進行修補，並持續追蹤可能存在的風險。\n辦理頻率：\n等級 | 頻率\nA 級 | 每年辦理 1 次\nB 級、C 級 | 每 2 年辦理 1 次\nD 級、E 級 | 無要求\n六個辦理項目與檢視內容（必背）：\n編號 | 檢視項目 | 檢視內容\n① | 網路架構檢視 | 針對網路架構圖進行安全性弱點檢視，詳列發現事項之風險等級、風險說明與改善建議\n② | 網路惡意活動檢視 | 架設「封包側錄設備」觀察內部電腦或設備是否有對外之異常連線\\n檢視資安設備紀錄檔，分析過濾是否有對外異常連線紀錄\\n發現異常者應確認使用狀況與用途\n③ | 使用者端電腦惡意活動檢視 | 檢視作業系統更新情形、應用程式安全性更新情形、是否使用已停止支援之作業系統或軟體、防毒軟體安裝更新及定期掃描結果之處理情形\n④ | 伺服器主機惡意活動檢視 | 同使用者端四項，另加「是否使用不合宜之作業系統」（伺服器比使用者端多這一項）\n⑤ | 目錄服務系統設定及防火牆連線設定檢視 | 目錄服務系統組態設定以「政府組態基準 (GCB)」內容為標準確認落實情形\\n檢視防火牆連線設定規則是否有安全性弱點，確認來源與目的 IP 及通訊埠連通之適切性\n⑥ | 核心資通系統資料庫安全檢視 | 五項：特權帳號管理及資料加密、存取授權及稽核紀錄、委外管理、備份保護、弱點管理\n注意：健診是 6 項，與安全性檢測（弱點掃描、滲透測試）是不同的應辦事項。"
