            "h": "⭐⭐ 網路區域規劃：目的與六個區域",
            "b": "簡報 3-50、簡報 3-51、簡報 3-52、簡報 3-53、簡報 3-54、簡報 3-55、簡報 3-56。\n規劃目的四項：\n－清楚界定規劃不同屬性的區域\n－作為存取控制與安全規劃的基準群組\n－避免來自內部與外部的攻擊\n－防範災害擴大\n六個建議區域：\n區域 | 規劃重點\n外部網路 | 機關對外網路區域，連接外部廣域網路 (WAN)\\n對內部需經過防火牆的存取控制\\n非允許的服務與來源不能進入其他區域\n內部網路 (LAN) | 包含機關使用者終端、資通系統等設備\\n利用 VLAN 與不同路由等方式切開\\n外部網路無法直接連線內部網路\\n可考慮架設代理伺服器控管與外部網段之連線\n非軍事區 (DMZ) | 主要放置機關對外服務伺服器（網頁伺服器、FTP 伺服器）\\n僅開放特定服務（特定 TCP Port）\\n需嚴密控管此區域到內部區域的存取\n網路管理區域 | 放置網路管理系統、認證系統、監控系統\\n應明確標示網路的路徑及維運方式\\n網路設備維運應與服務的網段有所區隔，避免服務網段被攻擊進而影響網路設備的管理\n網路紀錄區域 | 放置備份主機 (Backup Server) 與紀錄主機 (Log Server)\\n存放網段應特別規劃\\n僅允許設備備份與紀錄之發送及管理員管理連線行為\n實體隔離區域 | 依特定需求將部分區域執行實體隔離\\n「單向傳輸：僅可將資料傳出，不可傳入」\\n可能危害途徑包括破解門禁系統、利用隨身碟竊取資料、私接網路對機密主機連線"
