            "b": "簡報 3-64、簡報 3-65、簡報 3-66、簡報 3-67。\nCMMC 2.0：2024（簡報 3-64 為圖）——網路安全成熟度模型驗證 (Cybersecurity Maturity Model Certification)，是美國國防部供應鏈的資安防護框架，用以保護 FCI 與 CUI，分為三個等級，逐級累加實務要求：\n等級 | 名稱 | 保護對象 | 要求項數 | 評鑑方式\nLevel 1 | 基礎級 | FCI | 15 項 | 每年自我評鑑\nLevel 2 | 進階級 | CUI | 110 項（同 NIST SP 800-171） | 每 3 年第三方評鑑\nLevel 3 | 專家級 | CUI | 134 項（含 NIST SP 800-172 子集） | 每 3 年政府主導評鑑\nNIST SP 800-210（簡報 3-65、簡報 3-66 為圖）——雲端系統的一般存取控制指引。\nISO/IEC 27017:2015 雲端安全管理七項重點：\n雲端環境下的角色共享與權責\n雲端服務客戶資產的移除\n虛擬運算環境的區隔\n虛擬機器強化\n管理者的操作安全\n監控雲端服務\n虛擬及實體網路安全管理的一致性"
