            "b": "簡報 3-90。\n法源 | 規定內容\n資通安全管理法 §10（逐字背） | 公務機關或特定非公務機關，於本法適用範圍內，委外辦理資通系統之建置、維運或資通服務之提供，應「選任適當之受託者」、「要求受託者建立有效之資通安全管理機制」，並「監督該機制之實施」\n施行細則 §7 第 1 項 | 各機關依本法 §10 規定委外辦理受託業務，選任及監督受託者時，應注意八款事項（見下一條）\n施行細則 §9 第 1 項第 11 款 | 資通安全維護計畫應包含「資通系統或服務委外辦理之管理措施」\n分級辦法 §11 第 2 項 | 各機關「自行或委外」開發之資通系統應依附表九完成分級，並依附表十執行控制措施\n§10 的三個動作：選任 → 要求建立機制 → 監督機制之實施。"
