            "h": "⭐⭐ 施行細則 §7 第 1 項：委外選任及監督的八款注意事項",
            "b": "簡報 3-91。\n款次 | 注意事項\n一 | 受託者應配置「充足且經適當之資格訓練、擁有資通安全專業證照或具有類似業務經驗」之資通安全專業人員\n二 | 受託者辦理受託業務「得否複委託」、得複委託之範圍與對象，及複委託之受託者應具備之資通安全維護措施\n三 | 受託業務涉及國家機密者，執行受託業務之相關人員應接受「適任性查核」，並依國家機密保護法之規定管制其出境\n四 | 受託業務包括客製化資通系統開發者，受託者應提供該資通系統之「安全性檢測證明」\\n該資通系統屬委託機關之「核心資通系統」，或委託金額達「新臺幣一千萬元以上」者，委託機關應自行或另行委託「第三方」進行安全性檢測\\n涉及利用非受託者自行開發之系統或資源者，並應標示非自行開發之內容與其來源及提供授權證明\n五 | 受託者執行受託業務違反資安相關法令或知悉資安事件時，應「立即」通知委託機關及採行之補救措施\n六 | 委託關係「終止或解除」時，應確認受託者返還、移交、刪除或銷毀履行契約而持有之資料\n七 | 受託者應採取之其他資通安全相關維護措施\n八 | 委託機關應定期或於知悉受託者發生可能影響受託業務之資安事件時，以「稽核或其他適當方式」確認受託業務之執行情形\n必背數字：一千萬元；必背要件：屬核心資通系統「或」委託金額達一千萬元以上，兩者是「或」的關係，符合其一即須第三方檢測。"
