            "b": "簡報 3-92。\n法源：施行細則 §7 第 1 項第 8 款——委託機關應定期或於知悉受託者發生可能影響受託業務之資安事件時，以稽核或其他適當方式確認受託業務之執行情形。\n四個實務要點：\n委託機關對委外廠商之管理措施，應確保委託業務「如期如質」執行\n應檢視所有委外廠商；若囿於人力或經費不足無法每年確認所有廠商，建議參照「委外金額、涉及核心系統及業務性質」等面向擬定相關計畫，並以書面稽核或其他適當方式確認執行狀況\n應留存「監督（稽核）結果紀錄、委外廠商之改善報告、以及後續追蹤紀錄」三種文件\n可參考行政院 111 年 5 月 26 日院臺護字第 1110174630 號函訂定「資通系統籌獲各階段資安強化措施」\n考點：委外的責任不會外包出去——監督與留存紀錄是委託機關的義務。"
