            "h": "⭐⭐ 資訊委外之風險：遠端維運三大風險與「原則禁止、例外允許」",
            "b": "簡報 3-96。\n背景：近期迭發生機關開放委外廠商自遠端進行資通系統維護，致存取機制遭駭客利用、間接攻擊機關資通系統之事件。\n遠端維運的三大風險：\n風險 | 說明\n帳密被竊取 | VPN 或遠端帳號密碼遭竊取、盜用\n惡意程式植入 | 廠商維運主機被植入惡意程式，成為攻擊機關的跳板\n弱密碼或未限制來源 IP | 遠端桌面服務使用弱密碼或未限制來源 IP，易遭暴力破解\n原則（必背）：各機關開放機關內部同仁及委外廠商進行遠端維護資通系統，應採「原則禁止、例外允許」方式辦理。\n例外情形：因地理限制、處理時效及專案特性等因素須開放遠端存取時，應至少辦理下列三項防護措施：\n編號 | 防護措施\n① | 依施行細則 §7 及分級辦法附表十中有關「遠端存取」相關規定辦理，並建立及落實管理機制\n② | 開放遠端存取期間「原則以短天期為限」，並建立異常行為管理機制\n③ | 於結束遠端存取期間後，應「確實關閉網路連線，並更換遠端存取通道（如 VPN）登入密碼」\n最容易漏的是第三項的「更換 VPN 密碼」。"
