            "b": "簡報 3-97、簡報 3-98。\n步驟 | 對應採購階段 | 內容 \n① 決定需求 | 計畫階段 |機關對資通系統明確定義需求，並識別出資通安全的需求\n② 識別可行解決方案  | 計畫階段 | 在建置或選商前，審慎分析資訊作業環境現況與期望達成目標之差異，再識別出可行解決方案選項，並訂定適當的評估指標\n③ 選定解決方案 | 決標階段 | 由決策者選出適當的解決方案 \n④ 完成建置 | 履約管理階段 | 決標後成立專案組織，督導服務廠商遵循 RFP 與契約，如期如質完成系統建置與測試工作\n⑤ 確認營運服務正常 | 驗收階段 | 服務進入營運狀態，需持續量測服務水準是否滿足原規劃需求\n配對陷阱有兩個：①前「兩個」步驟都對應計畫階段 ②生命週期沒有對應到「招標」與「保固」兩個階段。"
