            "h": "⭐⭐ 資安要求的六個採購階段",
            "b": "簡報 3-99。\n依一般採購流程區分為六個階段，各階段的資安控管重點如下（細節見本節後續各條）：\n階段 | 資安重點 | 詳見\n① 計畫階段 | 評估個案之委外可行性與委外風險，以確認是否進行委外\\n分為委外可行性分析、委外專案編成、委外資安需求識別三步驟 | 「計畫階段：三步驟與可行性分析」\n② 招標階段 | 遴選適宜之委外廠商\\n著重「RFP 撰寫之完整度」與「評選準則中之資安要求符合度」\\nRFP 及契約書應依系統等級納入防護基準之 SSDLC 六階段規定 | 「招標階段與決標階段」\n③ 決標階段 | 與廠商之簽約作業\\n兩個重點——查核廠商是否完成「保密切結」、完成「專案編組」 | 同上\n④ 履約管理階段 | 七大面向：資通安全組織、風險持續識別、人力資源安全、實體與環境安全、委外管理、使用者存取管理、資通安全事件管理 | 「履約管理階段的七大面向」\n⑤ 驗收階段 | 依契約文件與履約管理成果辦理\\n勞務驗收得以書面或審查會辦理\\n四類別各有驗收重點\\n專案結束應立即停止實體與邏輯存取權限並回收或銷毀資產 | 「驗收階段：四類別的驗收內容與專案結束處置」\n⑥ 保固階段 | 以「維持驗收完成時之狀態」為目的\\n應受嚴格之變更管理控制\\n重大瑕疵屬廠商責任者由廠商另提變更計畫 | 「保固階段：保固服務與異常管理」\n順序必背，且注意「履約管理」在決標之後、驗收之前。"
