            "b": "簡報 3-116、簡報 3-117。\n資通安全事件分級由輕至重分「1」、「2」、「3」、「4」四個級別；各級的詳細判準見本節的「三構面四級對照總表」。\n綜評的四個要素：\n評定要素 | 內容 | 考點\n資訊或資通系統性質（四類） | ①核心業務資訊或資通系統（再分「涉及」與「未涉及」關鍵基礎設施 (CI) 維運）②非核心業務資訊或資通系統③一般公務機密④國家機密 | 「涉及 CI」與「國家機密」是把等級往上推的兩個關鍵字\nCIA 衝擊性（三構面） | ①機密性＝資訊遭洩漏②完整性＝資訊或資通系統遭竄改③可用性＝能否於可容忍中斷時間內回復 | 三構面各自評級，某一構面未受影響時該構面為「無需通報」\n影響程度 | 輕微／嚴重兩檔 | 輕微或嚴重由政府機關依所造成之影響「自行認定」其嚴重性\n綜評方式 | 以最高級別評為該資通安全事件通報等級 | 陷阱：不是取平均、不是多數決，也不是只看可用性——三構面分別評級後取最高者\n兩個必背定義（逐字背）：\n名詞 | 出處 | 定義\n一般公務機密 | 文書處理手冊第 51 項 | 指本機關持有或保管之資訊，除國家機密外，依法令有保密義務者\n國家機密 | 國家機密保護法 §2 及 §4 | 指為確保國家安全或利益而有保密之必要，對政府機關持有或保管之資訊，經依本法核定機密等級者（絕對機密、極機密、機密）\n必考觀念：三構面分別評級後「取最高者」為該事件等級；性質越敏感（國家機密、涉及 CI）、程度越嚴重，級別越高。"
