            "b": "簡報 3-120。\n依「受影響資通系統性質與可否於可容忍中斷時間回復」評估級別：\n級別 | 判準\n第 1 級 | 非核心資通系統之運作受影響或停頓，「於」可容忍中斷時間內回復正常運作，造成機關日常作業影響\n第 2 級 | 非核心資通系統「無法於」可容忍中斷時間內回復，或未涉及 CI 維運之核心資通系統「於」可容忍中斷時間內回復\n第 3 級 | 未涉及 CI 維運之核心資通系統「無法於」可容忍中斷時間內回復，或涉及 CI 維運之核心資通系統「於」可容忍中斷時間內回復\n第 4 級 | 涉及 CI 維運之核心資通系統之運作受影響或停頓，「無法於」可容忍中斷時間內回復正常運作\n可容忍中斷時間：政府機關應考量業務性質及影響程度等因素，評定可容許的中斷時間。\n判準口訣：系統重要性往上一階、或「不能在時間內回復」，就往上一級。"
