            "h": "⭐ 事件處理的三類相關訊息",
            "b": "簡報 3-124。\n事件處理過程會產生三類訊息，分別對應三個時點：通報當下、處理中、結案後提交報告。\n訊息類別 | 應包含之項目 | 提醒\n資安事件通報基本項目（七項） | ①發生機關②發生或知悉時間③狀況之描述④等級之評估⑤因應事件所採取之措施⑥外部支援需求評估⑦其他相關事項 | 通報當下就要填的欄位；易漏「外部支援需求評估」\n損害控制內容 | 根據機關內部處理資安事件之程序，記錄損害控制或復原之歷程 | 只有一句，重點在「記錄歷程」\n調查、處理及改善報告（七項） | ①事件發生或知悉其發生、完成損害控制或復原作業之時間②事件影響之範圍及損害評估③損害控制及復原作業之歷程④事件調查及處理作業之歷程⑤事件根因分析⑥為防範類似事件再次發生所採取之管理、技術、人力或資源等層面之措施⑦預定完成時程及成效追蹤機制 | 易漏兩項：「事件根因分析」與「預定完成時程及成效追蹤機制」\n辨析：\n通報基本項目是「事件當下的描述」\n改善報告則要求「時間、範圍、歷程、根因、防範措施、追蹤機制」六類內容"
