            "b": "簡報 3-125、簡報 3-126、簡報 3-127、簡報 3-128。\n時限鏈總表（全單元最必背）：\n階段 | 誰做什麼 | 第 1、2 級 | 第 3、4 級\n① 通報 | 公務機關 向 上級或監督機關 及 主管機關 通報（無上級或監督機關者，總統府、國家安全會議及五院向主管機關提出；直轄市／縣市政府及議會向主管機關提出；區公所、鄉鎮市公所及各該民代表會向直轄市或縣政府提出）\\n特定非公務機關 向 中央目的事業主管機關 通報 | 知悉後 1 小時內 | 知悉後 1 小時內\n② 審核 | 受通報機關完成事件等級之審核，並得依審核結果變更其等級 | 接獲後 8 小時內 | 接獲後 2 小時內\n③ 轉知 | 受通報機關將審核結果通知主管機關，並提供審核依據之相關資訊 | 1 小時內 | 1 小時內\n④ 損害控制或復原 | 事件機關於限定時間內儘速完成 | 72 小時內 | 36 小時內\n⑤ 調查、處理及改善報告 | 事件機關提交，視情況可提出延後提交申請 | 1 個月內 | 1 個月內\n沒有時限、但一樣必背的三件事：\n事項 | 誰做 | 內容\n覆核 | 主管機關 | 接獲審核結果之通知後，應依相關資訊就事件等級進行覆核，並得依覆核結果變更其等級。\\n覆核範圍的「應／得」之分（必考）：對公務機關之事件「應」覆核第 1 級至第 4 級；對特定非公務機關之事件「得」覆核第 1 級至第 4 級——兩者範圍都是全部等級，差別只在「應」與「得」\n逕為審核 | 主管機關 | 認有必要，或受通報機關未依規定通知審核結果時，得就該事件逕為審核，並得為等級之變更\n等級變更申請 | 通報機關 | 於事件調查過程中發現影響範圍擴大時，應適時提出等級變更申請，並說明變更原因與事件調查情況，以利審核機關或主管機關儘早知悉並適時提供必要支援\n數字鏈（一口氣背）：通報 1 小時 → 審核 8 小時（1、2 級）／2 小時（3、4 級）→ 轉知 1 小時 → 損害控制或復原 72 小時（1、2 級）／36 小時（3、4 級）→ 報告 1 個月。\n易混：審核與損害控制都是「級別越高越快」（8→2 小時、72→36 小時），但兩組數字別配錯。\n陷阱：只有「審核」與「損害控制或復原」分等級，通報 1 小時、轉知 1 小時、報告 1 個月是不分等級的。\n簡報 3-127、3-128 分別為公務機關與特定非公務機關的通報及應變作業流程圖。"
